const DB_NAME='nutri-db',DB_VERSION=4,STORES=['settings','foods','entries','water','weights','recipes','fasting','plans','activities'];let db,tab='home',date=today();const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID();function addDays(day,offset){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{for(let n of STORES)if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function all(store){return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function put(store,v){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(v);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}function del(store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const BACKUP_KEY='nutri-last-backup';const enc=new TextEncoder(),dec=new TextDecoder();function b64(bytes){let out='';for(let i=0;i<bytes.length;i+=8192)out+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(out)}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}async function derive(password,salt){let material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}async function seal(data,password){let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(password,salt),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(data))));return JSON.stringify({format:'NUTRI-ENCRYPTED',version:1,kdf:'PBKDF2-SHA256',iterations:310000,cipher:'AES-256-GCM',salt:b64(salt),iv:b64(iv),data:b64(cipher)})}async function unseal(obj,password){if(obj.format!=='NUTRI-ENCRYPTED'||obj.version!==1||obj.iterations!==310000||typeof obj.salt!=='string'||typeof obj.iv!=='string'||typeof obj.data!=='string')throw Error('Format chiffré non reconnu');let salt=unb64(obj.salt),iv=unb64(obj.iv);if(salt.length!==16||iv.length!==12)throw Error('Paramètres de chiffrement invalides');let key=await derive(password,salt);return JSON.parse(dec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,unb64(obj.data))))}function validate(data){if(data?.version===1&&data.stores&&!data.stores.recipes)data.stores.recipes=[];if(data?.stores){for(const key of ['fasting','plans','activities'])if(!data.stores[key])data.stores[key]=[];}if(data.app!=='NUTRI'||![1,2,3].includes(data.version)||!data.stores||!STORES.every(s=>Array.isArray(data.stores[s])&&data.stores[s].every(x=>x&&typeof x.id==='string')))throw Error('Sauvegarde incompatible');for(const s of STORES){if(data.stores[s].length>200000)throw Error('Trop de données');for(const x of data.stores[s]){if(s==='entries'&&(!Number.isFinite(Number(x.grams))||Number(x.grams)<0))throw Error('Entrée invalide');if(s==='foods'&&typeof x.name!=='string')throw Error('Aliment invalide')}}return data}async function storageStatus(){let out='Stockage local actif';try{if(navigator.storage?.persisted){out+=(await navigator.storage.persisted())?' · persistance accordée':' · persistance non garantie'}if(navigator.storage?.estimate){let x=await navigator.storage.estimate();out+=` · ${Math.round((x.usage||0)/1024/1024*10)/10} Mo utilisés`}}catch{}return out}async function requestPersistence(){try{if(!navigator.storage?.persist)throw Error('Non pris en charge sur cet appareil');let ok=await navigator.storage.persist();toast(ok?'Persistance accordée':'Persistance non accordée');render()}catch(e){toast(e.message)}}
const n=x=>Math.max(0,Number(x)||0),fmt=x=>Math.round(x).toLocaleString('fr-FR');function totals(entries){return entries.reduce((a,e)=>{for(const k of ['kcal','protein','carbs','fat'])a[k]+=n(e[k])*n(e.grams)/100;return a},{kcal:0,protein:0,carbs:0,fat:0})}function toast(msg){let el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2600)}const icons={home:'<path d="M3 10 12 3l9 7v11H3z"/><path d="M9 21v-8h6v8"/>',diary:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',foods:'<circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/>',recipes:'<path d="M4 3h16v18H4z"/><path d="M8 8h8M8 12h8M8 16h5"/>',plans:'<path d="M4 5h16v16H4z"/><path d="M4 10h16M8 2v6M16 2v6"/>',activities:'<path d="M3 17l5-5 4 3 5-9 4 2"/><path d="M3 21h18"/>',fasting:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',photo:'<rect x="3" y="5" width="18" height="15" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M8 5l1-2h6l1 2"/>',progress:'<path d="M4 20V9m6 11V4m6 16v-7m5 7V7"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-8 16-8 16 0"/>'};const nav=[['home','Accueil'],['diary','Journal'],['foods','Aliments'],['photo','Photo'],['recipes','Recettes'],['plans','Menus'],['progress','Progrès'],['activities','Activités'],['fasting','Jeûne'],['profile','Profil']];function field(label,name,type='number',value='',other=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${other} required></label>`}function foodForm(){return `<form id="foodForm" class="card"><b>Créer un aliment</b><p class="notice">Valeurs pour 100 g. Vérifiez les étiquettes nutritionnelles.</p>${field('Nom','name','text','','maxlength="120"')}${field('Calories (kcal)','kcal','number','','min="0" step="0.01"')}<div class="formgrid">${field('Protéines (g)','protein','number',0,'min="0" step="0.01"')}${field('Glucides (g)','carbs','number',0,'min="0" step="0.01"')}${field('Lipides (g)','fat','number',0,'min="0" step="0.01"')}</div><button class="btn">Enregistrer l’aliment</button></form>`}async function render(){let settings=(await all('settings'))[0]||{id:'main',target:2000,protein:100,carbs:220,fat:70,waterTarget:2000};let entries=(await all('entries')).filter(e=>e.date===date),foods=await all('foods'),water=(await all('water')).filter(e=>e.date===date),recipes=await all('recipes'),weights=(await all('weights')).sort((a,b)=>b.date.localeCompare(a.date)),t=totals(entries),waterTotal=water.reduce((a,e)=>a+n(e.ml),0);let content='';if(tab==='home'){let remaining=settings.target-t.kcal;content=`<div class="eyebrow">Votre équilibre au quotidien</div><h1 class="title">Bonjour 👋</h1><div class="muted">Votre espace nutrition personnel</div><div class="card dark"><div class="row"><b>Énergie du jour</b><span class="pill">${esc(date)}</span></div><div class="hero" style="margin-top:18px"><div class="ring" style="--progress:${Math.min(100,t.kcal/settings.target*100||0)}%"><div class="ring-content"><strong>${fmt(Math.abs(remaining))}</strong><small>${remaining>=0?'kcal restantes':'kcal dépassées'}</small></div></div><div><div class="tiny" style="color:#c1d6d1">Consommées</div><div class="stat">${fmt(t.kcal)} <small style="font-size:13px">kcal</small></div><div class="tiny" style="margin-top:14px;color:#c1d6d1">Objectif quotidien</div><div class="stat">${fmt(settings.target)} <small style="font-size:13px">kcal</small></div></div></div></div><div class="sectionhead"><h2>Macronutriments</h2></div><div class="grid3">${[['Protéines','protein',settings.protein],['Glucides','carbs',settings.carbs],['Lipides','fat',settings.fat]].map(([label,key,target])=>`<div class="metric"><span class="tiny muted">${label}</span><b>${fmt(t[key])} g</b><span class="tiny muted">sur ${fmt(target)} g</span><div class="progress"><i style="width:${Math.min(100,t[key]/target*100||0)}%"></i></div></div>`).join('')}</div><div class="sectionhead"><h2>Hydratation</h2><span class="pill">${fmt(waterTotal)} / ${fmt(settings.waterTarget)} ml</span></div><div class="card"><div class="progress"><i style="width:${Math.min(100,waterTotal/settings.waterTarget*100||0)}%"></i></div><div class="actions" style="margin-top:16px"><button class="btn alt" data-water="250">+ 250 ml</button><button class="btn alt" data-water="500">+ 500 ml</button><button class="btn alt" data-tab="diary">Ajouter un repas</button></div></div><div class="sectionhead"><h2>Derniers aliments</h2></div><div class="card">${entries.length?entries.slice(-4).reverse().map(e=>`<div class="entry"><div><b>${esc(e.name)}</b><small>${fmt(e.grams)} g</small></div><b>${fmt(e.kcal*e.grams/100)} kcal</b></div>`).join(''):'<div class="empty">Aucun aliment pour cette journée.</div>'}</div>`}if(tab==='diary'){content=`<div class="eyebrow">Suivi quotidien</div><h1 class="title">Journal alimentaire</h1><div class="card"><div class="row"><label class="field" style="margin:0">Date<input id="dateInput" class="dateinput" type="date" value="${date}"></label><div style="text-align:right"><div class="stat">${fmt(t.kcal)}</div><div class="tiny muted">kcal consommées</div></div></div></div><form id="entryForm" class="card"><b>Ajouter au journal</b><label class="field" style="margin-top:14px">Aliment<select name="food" required><option value="">Sélectionner un aliment</option>${[...foods].sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||a.name.localeCompare(b.name,'fr')).map(f=>`<option value="${esc(f.id)}">${esc(f.name)} · ${fmt(f.kcal)} kcal / 100 g</option>`).join('')}</select></label>${field('Quantité (grammes)','grams','number',100,'min="0.1" step="0.1"')}<label class="field">Repas<select name="meal"><option>Petit-déjeuner</option><option>Déjeuner</option><option>Dîner</option><option>Collation</option></select></label><button class="btn" ${foods.length?'':'disabled'}>Ajouter</button>${foods.length?'':'<p class="notice">Créez d’abord un aliment dans le catalogue.</p>'}</form><div class="sectionhead"><h2>Aliments enregistrés</h2></div><div class="card">${entries.length?entries.map(e=>`<div class="entry"><div><b>${esc(e.name)}</b><small>${esc(e.meal)} · ${fmt(e.grams)} g · ${fmt(e.kcal*e.grams/100)} kcal</small></div><div class="actions"><button class="btn alt small" data-edit-entry="${esc(e.id)}">Modifier</button><button class="btn alt small" data-copy-entry="${esc(e.id)}">Dupliquer</button><button class="btn danger small" data-delete-entry="${esc(e.id)}" aria-label="Supprimer ${esc(e.name)}">Supprimer</button></div></div>`).join(''):'<div class="empty">Votre journal est vide.</div>'}</div>`}if(tab==='foods'){content=`<div class="eyebrow">Catalogue alimentaire</div><h1 class="title">Rechercher des aliments</h1><div class="card"><form id="offSearch"><label class="field">Produit ou marque<input name="query" type="search" minlength="2" maxlength="100" placeholder="Ex. yaourt nature, pâtes, Danone" required></label><button class="btn">Rechercher en ligne</button></form><p class="notice">Recherche Open Food Facts : connexion nécessaire. Les aliments ajoutés restent disponibles hors ligne. Vérifiez les valeurs nutritionnelles.</p><div id="offResults" aria-live="polite"></div></div>`+`<div class="eyebrow">Bibliothèque personnelle</div><h1 class="title">Mes aliments</h1><p class="muted">Catalogue personnel disponible hors ligne.</p>${foodForm()}<div class="sectionhead"><h2>Catalogue (${foods.length})</h2></div><div class="card">${foods.length?foods.map(f=>`<div class="entry"><div><b>${esc(f.name)}</b><small>${fmt(f.kcal)} kcal · P ${fmt(f.protein)} g · G ${fmt(f.carbs)} g · L ${fmt(f.fat)} g / 100 g</small></div><div class="actions"><button class="btn alt small" data-favorite-food="${esc(f.id)}" aria-label="Favori">${f.favorite?"★ Favori":"☆ Favori"}</button><button class="btn danger small" data-delete-food="${esc(f.id)}">Supprimer</button></div></div>`).join(''):'<div class="empty">Aucun aliment créé.</div>'}</div>`}if(tab==='recipes'){content=`<div class="eyebrow">Cuisine personnalisée</div><h1 class="title">Mes recettes</h1><p class="muted">Calculez les valeurs de vos recettes à partir de vos aliments personnels, puis ajoutez une portion au journal.</p><form id="recipeForm" class="card"><h2>Créer une recette</h2>${field('Nom de la recette','name','text','','maxlength="120"')}${field('Nombre de portions','servings','number',2,'min="1" max="100" step="1"')}<div id="ingredients">${ingredientRow(foods,0)}</div><div class="actions"><button type="button" class="btn alt" id="addIngredient">+ Ingrédient</button><button class="btn" ${foods.length?'':'disabled'}>Enregistrer la recette</button></div>${foods.length?'':'<p class="notice">Ajoutez d’abord des aliments dans le catalogue.</p>'}</form><div class="sectionhead"><h2>Recettes (${recipes.length})</h2></div><div class="card">${recipes.length?recipes.map(r=>{let per=recipeTotals(r);return `<div class="entry"><div><b>${esc(r.name)}</b><small>${fmt(per.kcal)} kcal / portion · P ${fmt(per.protein)} g · G ${fmt(per.carbs)} g · L ${fmt(per.fat)} g</small><small>${fmt(r.servings)} portions · ${r.ingredients.length} ingrédients</small></div><div class="actions"><button class="btn small" data-add-recipe="${esc(r.id)}">+ Journal</button><button class="btn danger small" data-delete-recipe="${esc(r.id)}">Supprimer</button></div></div>`}).join(''):'<div class="empty">Aucune recette enregistrée.</div>'}</div>`}if(tab==='progress'){let history=(await all('entries')).reduce((a,e)=>{(a[e.date]??=[]).push(e);return a},{});let days=Number(sessionStorage.getItem('nutri-stats-days')||30);if(![7,30,90].includes(days))days=30;let dates=Array.from({length:days},(_,i)=>addDays(today(),i-days+1));let values=dates.map(d=>({date:d,...totals(history[d]||[]),recorded:!!history[d]?.length}));let logged=values.filter(v=>v.recorded),sum=logged.reduce((a,v)=>a+v.kcal,0),avg=logged.length?sum/logged.length:0,max=Math.max(settings.target||1,...values.map(v=>v.kcal));let macroAvg=k=>logged.length?logged.reduce((a,v)=>a+v[k],0)/logged.length:0;let chart=values.map(v=>`<div class="statbar" title="${esc(v.date)} : ${fmt(v.kcal)} kcal"><div class="statbarfill ${v.recorded?'':'statbarmissing'}" style="height:${v.recorded?Math.max(2,Math.min(100,v.kcal/max*100)):2}%"></div></div>`).join('');let weightAsc=[...weights].sort((a,b)=>a.date.localeCompare(b.date)),first=weightAsc[0],last=weightAsc.at(-1),delta=first&&last&&first!==last?last.kg-first.kg:null;content=`<div class="eyebrow">Votre évolution</div><h1 class="title">Progrès</h1><div class="card"><div class="row"><h2>Analyse nutritionnelle</h2><select id="statsPeriod" aria-label="Période statistique"><option value="7" ${days===7?'selected':''}>7 jours</option><option value="30" ${days===30?'selected':''}>30 jours</option><option value="90" ${days===90?'selected':''}>90 jours</option></select></div><div class="grid3"><div class="metric"><span class="tiny muted">Moyenne / jour renseigné</span><b>${fmt(avg)} kcal</b></div><div class="metric"><span class="tiny muted">Jours renseignés</span><b>${logged.length} / ${days}</b></div><div class="metric"><span class="tiny muted">Objectif</span><b>${fmt(settings.target)} kcal</b></div></div><div class="statgraph" role="img" aria-label="Calories par jour sur ${days} jours">${chart}</div><div class="row tiny muted"><span>${esc(dates[0])}</span><span>${esc(dates.at(-1))}</span></div><p class="notice">Les jours sans repas enregistré sont exclus des moyennes et représentés par une barre discrète, pas par 0 kcal consommée.</p><div class="grid3">${[['Protéines','protein'],['Glucides','carbs'],['Lipides','fat']].map(([label,key])=>`<div class="metric"><span class="tiny muted">${label} / jour</span><b>${fmt(macroAvg(key))} g</b></div>`).join('')}</div><button class="btn alt" id="exportStats">Exporter l'historique CSV</button></div><div class="card"><h2>Enregistrer mon poids</h2><form id="weightForm">${field('Date','date','date',today())}${field('Poids (kg)','kg','number','','min="1" max="500" step="0.1"')}<button class="btn">Enregistrer</button></form>${last?`<p class="notice">Dernière mesure : ${n(last.kg).toLocaleString('fr-FR')} kg (${esc(last.date)})${delta!==null?' · Évolution depuis la première mesure : '+(delta>0?'+':'')+delta.toFixed(1)+' kg':''}</p>`:''}</div><div class="sectionhead"><h2>Historique du poids</h2></div><div class="card">${weights.length?weights.map(w=>`<div class="entry"><span>${esc(w.date)}</span><b>${n(w.kg).toLocaleString('fr-FR')} kg</b></div>`).join(''):'<div class="empty">Aucune mesure enregistrée.</div>'}</div>`}if(tab==='profile'){content=`<div class="eyebrow">Vos préférences</div><h1 class="title">Profil et données</h1><form id="settingsForm" class="card"><h2>Objectifs quotidiens</h2>${field('Calories (kcal)','target','number',settings.target,'min="1" max="20000"')}${field('Protéines (g)','protein','number',settings.protein,'min="1" max="2000"')}${field('Glucides (g)','carbs','number',settings.carbs,'min="1" max="2000"')}${field('Lipides (g)','fat','number',settings.fat,'min="1" max="2000"')}${field('Hydratation (ml)','waterTarget','number',settings.waterTarget,'min="1" max="20000"')}<button class="btn">Enregistrer mes objectifs</button></form><div class="card"><h2>Estimer mes besoins énergétiques</h2><p class="notice">Estimation indicative selon Mifflin–St Jeor. Ne remplace pas un avis médical. Les objectifs ne sont jamais modifiés sans confirmation.</p><form id="energyForm"><div class="formgrid"><label class="field">Formule de référence<select name="formula"><option value="female">Femme</option><option value="male">Homme</option></select></label>${field('Âge (années)','age','number','','min="18" max="110"')}${field('Taille (cm)','height','number','','min="100" max="250"')}${field('Poids (kg)','weight','number','','min="25" max="350" step="0.1"')}</div><label class="field">Activité habituelle<select name="activity"><option value="1.2">Sédentaire</option><option value="1.375">Légèrement active</option><option value="1.55">Modérément active</option><option value="1.725">Très active</option></select></label><label class="field">Objectif<select name="goal"><option value="0">Maintien</option><option value="-250">Perte progressive (−250 kcal)</option><option value="-500">Perte modérée (−500 kcal)</option><option value="250">Prise progressive (+250 kcal)</option></select></label><button class="btn alt">Calculer l’estimation</button></form><div id="energyResult" aria-live="polite"></div></div><div class="card"><h2>Rappels personnalisés</h2><p class="notice">Rappels locaux visibles lorsque NUTRI est ouvert. Sur iPhone, une PWA fermée ne peut pas garantir des rappels programmés sans serveur de notifications.</p><form id="reminderForm"><label class="field">Rappel de repas<input type="time" name="mealTime" value="${esc(settings.mealTime||'12:30')}" required></label><label class="field">Rappel d’hydratation<input type="time" name="waterTime" value="${esc(settings.waterTime||'16:00')}" required></label><label class="field"><input type="checkbox" name="remindersEnabled" ${settings.remindersEnabled?'checked':''}> Activer les rappels pendant l’utilisation</label><button class="btn alt">Enregistrer les rappels</button></form><p class="notice" id="reminderStatus">${settings.remindersEnabled?'Rappels activés pendant l’utilisation':'Rappels désactivés'}</p><button type="button" id="testReminder" class="btn alt">Tester une notification</button></div><div class="card"><h2>Sauvegardes manuelles</h2><p class="notice">Sauvegarde chiffrée AES-256-GCM avec mot de passe. Enregistrez le fichier dans Fichiers ou iCloud Drive. Sans mot de passe, la restauration est impossible.</p><p class="notice" id="backupAge">Dernière sauvegarde : vérification…</p><p class="notice" id="storageStatus">Vérification du stockage…</p><div class="actions"><button id="exportBtn" class="btn">Exporter</button><button id="importBtn" class="btn alt">Restaurer</button><button id="persistBtn" type="button" class="btn alt">Protéger le stockage</button><input id="importFile" class="hidden" type="file" accept="application/json,.json,.nutri"></div></div><div class="card"><h2>Confidentialité</h2><p class="notice">Toutes les données restent dans ce navigateur. Aucun compte, suivi publicitaire ni transmission vers un serveur n'est prévu dans cette version. Une suppression des données Safari peut effacer votre journal.</p></div>`}
if(tab==='foods'){content+=`<section class="card"><h2>Code-barres</h2><p class="notice">Saisissez le code EAN du produit. Sur les navigateurs compatibles, utilisez aussi la caméra.</p><form id="barcodeForm" class="actions"><input id="barcodeInput" aria-label="Code-barres EAN" inputmode="numeric" pattern="[0-9]{8,14}" maxlength="14" placeholder="Code-barres (8 à 14 chiffres)" required><button class="btn">Rechercher</button></form><div class="actions" style="margin-top:10px"><button type="button" id="scanStart" class="btn alt">Scanner avec la caméra</button><button type="button" id="scanStop" class="btn alt hidden">Arrêter</button></div><video id="scanVideo" playsinline muted class="hidden scanvideo"></video><div class="actions" style="margin-top:10px"><label class="btn alt" for="barcodePhoto">Lire une photo de code-barres</label><input type="file" id="barcodePhoto" accept="image/*" capture="environment" class="hidden" aria-label="Photo du code-barres"></div><p id="scanStatus" class="notice" aria-live="polite">Si la caméra ne fonctionne pas, saisissez le code manuellement.</p><div id="barcodeResults" aria-live="polite"></div></section>`}
if(tab==='activities'){let acts=(await all('activities')).filter(a=>a.date===date).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),burn=acts.reduce((a,x)=>a+n(x.kcal),0);content=`<div class="eyebrow">Mouvement et bien-être</div><h1 class="title">Activités physiques</h1><div class="card"><div class="row"><label class="field">Date<input type="date" id="dateInput" value="${date}"></label><div><div class="stat">${fmt(burn)}</div><div class="tiny muted">kcal déclarées</div></div></div><p class="notice">Les calories dépensées sont des estimations saisies par vos soins. Elles ne sont pas automatiquement déduites de votre objectif alimentaire.</p></div><form id="activityForm" class="card"><h2>Ajouter une activité</h2>${field('Activité','name','text','','maxlength="100"')}${field('Durée (minutes)','minutes','number',30,'min="1" max="1440" step="1"')}${field('Calories dépensées estimées','kcal','number',0,'min="0" max="10000" step="1"')}<button class="btn">Enregistrer</button></form><div class="sectionhead"><h2>Activités du jour</h2></div><div class="card">${acts.length?acts.map(a=>`<div class="entry"><div><b>${esc(a.name)}</b><small>${fmt(a.minutes)} min · ${fmt(a.kcal)} kcal</small></div><button class="btn alt small" data-activity-delete="${esc(a.id)}">Supprimer</button></div>`).join(''):'<div class="empty">Aucune activité enregistrée.</div>'}</div>`;}if(tab==='fasting'){let sessions=(await all('fasting')).sort((a,b)=>b.start.localeCompare(a.start)),active=sessions.find(x=>!x.end);content=`<div class="eyebrow">Bien-être</div><h1 class="title">Jeûne intermittent</h1><div class="card"><h2>${active?'Session en cours':'Nouvelle session'}</h2><p class="notice">Suivi facultatif. Ne commencez pas de jeûne sans avis médical en cas de diabète traité par insuline, grossesse ou antécédents de troubles alimentaires.</p>${active?`<p>Début : <b>${new Date(active.start).toLocaleString('fr-FR')}</b></p><button class="btn" id="fastStop">Terminer la session</button>`:`<form id="fastStart"><label class="field">Objectif indicatif<select name="hours"><option value="12">12 heures</option><option value="14">14 heures</option><option value="16">16 heures</option></select></label><button class="btn">Démarrer</button></form>`}</div><div class="card"><h2>Historique</h2>${sessions.length?sessions.slice(0,20).map(x=>`<div class="entry"><div><b>${new Date(x.start).toLocaleString('fr-FR')}</b><small>${x.end?((new Date(x.end)-new Date(x.start))/36e5).toFixed(1)+' h':'En cours'} · objectif ${x.hours} h</small></div><button class="btn danger small" data-fast-delete="${esc(x.id)}">Supprimer</button></div>`).join(''):'<p class="empty">Aucune session.</p>'}</div>`}

if(tab==='plans'){
const plans=(await all('plans')).sort((a,b)=>a.date.localeCompare(b.date));
const meals=['Petit-déjeuner','Déjeuner','Dîner','Collation'];
const chosen=plans.filter(p=>p.date===date);
const sums=chosen.reduce((t,p)=>{const r=recipes.find(r=>r.id===p.recipeId);if(r){const v=recipeTotals(r);for(const k of ['kcal','protein','carbs','fat'])t[k]+=v[k]*n(p.servings)}return t},{kcal:0,protein:0,carbs:0,fat:0});
const shopping=new Map();for(const p of plans.filter(x=>x.date>=date&&x.date<=addDays(date,6))){const r=recipes.find(x=>x.id===p.recipeId);if(!r)continue;for(const ing of r.ingredients){const key=ing.foodId||ing.id||ing.name;const prev=shopping.get(key)||{name:ing.name,grams:0};prev.grams+=n(ing.grams)*n(p.servings)/Math.max(1,n(r.servings));shopping.set(key,prev)}}
content=`<div class="eyebrow">Organisation</div><h1 class="title">Menus & courses</h1><div class="card"><label class="field">Date<input type="date" id="planDate" value="${esc(date)}"></label><p class="notice">Planifiez vos recettes. Les menus ne sont pas ajoutés automatiquement au journal.</p><form id="planForm"><label class="field">Recette<select name="recipeId" required><option value="">Choisir une recette</option>${recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></label><label class="field">Repas<select name="meal">${meals.map(m=>`<option>${m}</option>`).join('')}</select></label>${field('Nombre de portions','servings','number',1,'min="0.25" max="50" step="0.25"')}<button class="btn" ${recipes.length?'':'disabled'}>Planifier</button></form></div><div class="card"><h2>Menus du ${esc(date)}</h2>${chosen.length?chosen.map(p=>{const r=recipes.find(x=>x.id===p.recipeId);return `<div class="entry"><div><b>${esc(p.meal)} · ${esc(r?.name||'Recette supprimée')}</b><small>${fmt(p.servings)} portion(s)</small></div><button class="btn danger small" data-plan-delete="${esc(p.id)}">Supprimer</button></div>`}).join(''):'<p class="empty">Aucun menu planifié.</p>'}<p class="notice">Total planifié : ${fmt(sums.kcal)} kcal · P ${fmt(sums.protein)} g · G ${fmt(sums.carbs)} g · L ${fmt(sums.fat)} g</p></div><div class="card"><h2>Liste de courses — 7 jours</h2><p class="notice">Du ${esc(date)} au ${addDays(date,6)}. Les quantités sont estimées à partir des recettes enregistrées.</p>${shopping.size?[...shopping.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(x=>`<div class="entry"><b>${esc(x.name)}</b><span>${Math.round(x.grams*10)/10} g</span></div>`).join(''):'<p class="empty">Planifiez des recettes pour générer la liste.</p>'}<button class="btn alt" id="copyShopping" ${shopping.size?'':'disabled'}>Copier la liste</button></div>`;
window.__nutriShopping=[...shopping.values()].map(x=>`${x.name} : ${Math.round(x.grams*10)/10} g`).join('\n');
}
if(tab==='progress'){let recent=(await all('entries')), days=Array.from({length:7},(_,i)=>{let d=new Date(date+'T12:00:00');d.setDate(d.getDate()-(6-i));let key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return {key,day:d.toLocaleDateString('fr-FR',{weekday:'short'}),total:totals(recent.filter(e=>e.date===key))}});let peak=Math.max(1,...days.map(d=>d.total.kcal));content+=`<section class="card"><h2>Calories — 7 jours</h2><div class="bars">${days.map(d=>`<div class="barcol"><b>${fmt(d.total.kcal)}</b><div class="bartrack"><i style="height:${Math.round(d.total.kcal/peak*100)}%"></i></div><small>${esc(d.day)}</small></div>`).join('')}</div><p class="notice">Moyenne : ${fmt(days.reduce((a,d)=>a+d.total.kcal,0)/7)} kcal/jour. Les jours sans saisie comptent pour zéro.</p></section>`}
if(tab==='photo'){content=`<div class="eyebrow">Saisie assistée</div><h1 class="title">Repas en photo</h1><div class="card"><p class="notice">La photo reste sur cet appareil et n'est pas transmise. Cette version ne reconnaît pas automatiquement les aliments : sélectionnez-les et confirmez les quantités.</p><label class="field">Photographier ou choisir une image<input id="mealPhoto" type="file" accept="image/*" capture="environment"></label><img id="mealPreview" alt="Aperçu du repas" class="hidden" style="max-width:100%;max-height:320px;object-fit:contain;border-radius:14px;margin:12px 0"><p id="mealPhotoStatus" class="tiny muted">Aucune image sélectionnée.</p></div><form id="photoMealForm" class="card"><h2>Composer le repas</h2><label class="field">Type de repas<select name="meal"><option>Petit-déjeuner</option><option>Déjeuner</option><option>Dîner</option><option>Collation</option></select></label><div id="photoMealRows"></div><button class="btn alt" type="button" id="photoAddRow">+ Ajouter un aliment</button><div id="photoTotal" class="notice" aria-live="polite">Ajoutez des aliments pour calculer les apports.</div><button class="btn" type="submit">Enregistrer les aliments dans le journal</button></form>`;}
$('#app').innerHTML=`<main class="shell"><header class="top"><div class="brand">NUT<span>RI</span><span style="font-size:10px;letter-spacing:0;color:#83958e;margin-left:8px">V2.2.0</span></div><span class="pill">● Hors ligne</span></header>${content}</main><nav class="nav" aria-label="Navigation principale"><div class="navinner">${nav.map(([key,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}" aria-label="${label}"><svg viewBox="0 0 24 24">${icons[key]}</svg>${label}</button>`).join('')}</div></nav>`;bind()}function ingredientRow(foods,i){return `<div class="formgrid ingredient-row" style="align-items:end"><label class="field">Aliment<select name="ingredientFood" required>${foods.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label>${field('Quantité (g)','ingredientGrams','number',100,'min="0.1" step="0.1"')}</div>`}function recipeTotals(r){let t={kcal:0,protein:0,carbs:0,fat:0};for(let i of r.ingredients){for(let k of Object.keys(t))t[k]+=n(i[k])*n(i.grams)/100}for(let k of Object.keys(t))t[k]/=Math.max(1,n(r.servings));return t}function offNutriments(product){const v=product.nutriments||{};const val=k=>{let x=Number(v[k+'_100g']);return Number.isFinite(x)&&x>=0?Math.round(x*100)/100:0};let kcal=val('energy-kcal');if(!kcal&&Number.isFinite(Number(v['energy-kj_100g'])))kcal=Math.round(Number(v['energy-kj_100g'])*0.239006);return {kcal,protein:val('proteins'),carbs:val('carbohydrates'),fat:val('fat')}}
async function searchOFF(e){e.preventDefault();const target=$('#offResults');const q=String(new FormData(e.target).get('query')||'').trim();if(q.length<2)return;target.textContent='Recherche en cours…';try{const u=new URL('https://world.openfoodfacts.org/cgi/search.pl');u.searchParams.set('search_terms',q);u.searchParams.set('search_simple','1');u.searchParams.set('action','process');u.searchParams.set('json','1');u.searchParams.set('page_size','20');u.searchParams.set('fields','code,product_name,brands,nutriments');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);let res;try{res=await fetch(u.toString(),{signal:controller.signal,headers:{Accept:'application/json'}})}finally{clearTimeout(timer)}if(!res.ok)throw Error('Service indisponible ('+res.status+')');let data=await res.json();let products=(data.products||[]).filter(p=>p.product_name&&p.nutriments&&Object.keys(p.nutriments).length);target.innerHTML=products.length?'<p class="notice">'+products.length+' résultat(s) · valeurs pour 100 g</p>'+products.map((p,i)=>{let v=offNutriments(p);return `<div class="entry"><div><b>${esc(p.product_name)}</b><small>${esc(p.brands||'Marque non renseignée')} · ${fmt(v.kcal)} kcal · P ${fmt(v.protein)} g · G ${fmt(v.carbs)} g · L ${fmt(v.fat)} g</small></div><button type="button" class="btn alt small" data-off-add="${i}">Ajouter</button></div>`}).join(''):'<p class="empty">Aucun résultat. Essayez une recherche plus précise.</p>';target.querySelectorAll('[data-off-add]').forEach(btn=>btn.onclick=async()=>{let p=products[Number(btn.dataset.offAdd)],v=offNutriments(p);let code=String(p.code||'');let food={id:code?'off:'+code:uid(),name:String(p.product_name).trim().slice(0,120),brand:String(p.brands||'').slice(0,120),source:'Open Food Facts',barcode:code,...v};try{await put('foods',food);toast('Aliment ajouté au catalogue');render()}catch(err){alert('Enregistrement impossible : '+err.message)}})}catch(err){target.textContent='Recherche impossible : vérifiez votre connexion ou réessayez. '+err.message}}
async function exportStatsCSV(){let entries=await all('entries'),byDate={};for(let e of entries)(byDate[e.date]??=[]).push(e);let dates=Object.keys(byDate).sort();let rows=[['Date','Calories (kcal)','Proteines (g)','Glucides (g)','Lipides (g)'],...dates.map(d=>{let t=totals(byDate[d]);return[d,...['kcal','protein','carbs','fat'].map(k=>t[k].toFixed(2))]})];let csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='NUTRI_historique_'+today()+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Export CSV préparé : enregistrez-le dans Fichiers')}
function bindActivities(){document.querySelector('#activityForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target),name=String(f.get('name')||'').trim(),minutes=Number(f.get('minutes')),kcal=Number(f.get('kcal'));if(!name||name.length>100||!Number.isFinite(minutes)||minutes<1||minutes>1440||!Number.isFinite(kcal)||kcal<0||kcal>10000)return toast('Activité invalide');try{await put('activities',{id:uid(),name,minutes,kcal,date,createdAt:new Date().toISOString()});toast('Activité enregistrée');render()}catch(e){toast('Échec de l’enregistrement : '+e.message)}});document.querySelectorAll('[data-activity-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer cette activité ?'))return;try{await del('activities',b.dataset.activityDelete);render()}catch(e){toast('Suppression impossible : '+e.message)}})}
function bind(){bindPhotoMeal();bindActivities();bindExtended();$('#statsPeriod')?.addEventListener('change',e=>{sessionStorage.setItem('nutri-stats-days',e.target.value);render()});$('#exportStats')?.addEventListener('click',exportStatsCSV);$('#offSearch')?.addEventListener('submit',searchOFF);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stopScan();clearPhotoURL();tab=b.dataset.tab;render()});document.querySelectorAll('[data-water]').forEach(b=>b.onclick=async()=>{await put('water',{id:uid(),date,ml:Number(b.dataset.water)});render()});$('#dateInput')?.addEventListener('change',e=>{date=e.target.value;render()});$('#foodForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return;await put('foods',{id:uid(),name:f.name.trim(),kcal:n(f.kcal),protein:n(f.protein),carbs:n(f.carbs),fat:n(f.fat)});toast('Aliment enregistré');render()});$('#entryForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),food=(await all('foods')).find(x=>x.id===f.food);if(!food||n(f.grams)<=0)return;await put('entries',{...food,id:uid(),foodId:food.id,date,grams:n(f.grams),meal:f.meal});toast('Ajouté au journal');render()});document.querySelectorAll('[data-copy-entry]').forEach(b=>b.onclick=async()=>{const item=(await all('entries')).find(x=>x.id===b.dataset.copyEntry);if(!item)return;await put('entries',{...item,id:uid(),date});toast('Repas dupliqué');render()});document.querySelectorAll('[data-edit-entry]').forEach(b=>b.onclick=async()=>{const item=(await all('entries')).find(x=>x.id===b.dataset.editEntry);if(!item)return;const raw=prompt('Nouvelle quantité (g)',String(item.grams));if(raw===null)return;const grams=Number(raw.replace(',','.'));if(!Number.isFinite(grams)||grams<=0||grams>100000)return toast('Quantité invalide');const meal=prompt('Repas : Petit-déjeuner, Déjeuner, Dîner ou Collation',item.meal);if(meal===null)return;if(!['Petit-déjeuner','Déjeuner','Dîner','Collation'].includes(meal))return toast('Repas non reconnu');await put('entries',{...item,grams,meal});toast('Repas modifié');render()});document.querySelectorAll('[data-favorite-food]').forEach(b=>b.onclick=async()=>{const item=(await all('foods')).find(x=>x.id===b.dataset.favoriteFood);if(!item)return;await put('foods',{...item,favorite:!item.favorite});render()});document.querySelectorAll('[data-delete-entry]').forEach(b=>b.onclick=async()=>{await del('entries',b.dataset.deleteEntry);render()});document.querySelectorAll('[data-delete-food]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer cet aliment du catalogue ? Les entrées passées seront conservées.'))return;await del('foods',b.dataset.deleteFood);render()});$('#addIngredient')?.addEventListener('click',async()=>{let foods=await all('foods');$('#ingredients').insertAdjacentHTML('beforeend',ingredientRow(foods,0))});$('#recipeForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target),foods=await all('foods'),ids=f.getAll('ingredientFood'),grams=f.getAll('ingredientGrams');let ingredients=ids.map((id,i)=>{let food=foods.find(x=>x.id===id);return food?{...food,grams:Number(grams[i])}:null});let servings=Number(f.get('servings'));if(!f.get('name')?.trim()||!Number.isInteger(servings)||servings<1||ingredients.some(x=>!x||!Number.isFinite(x.grams)||x.grams<=0))return toast('Vérifiez les ingrédients');await put('recipes',{id:uid(),name:String(f.get('name')).trim(),servings,ingredients});toast('Recette enregistrée');render()});document.querySelectorAll('[data-delete-recipe]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer cette recette ?'))return;await del('recipes',b.dataset.deleteRecipe);render()});document.querySelectorAll('[data-add-recipe]').forEach(b=>b.onclick=async()=>{let r=(await all('recipes')).find(x=>x.id===b.dataset.addRecipe);if(!r)return;let meal=prompt('Repas : Petit-déjeuner, Déjeuner, Dîner ou Collation','Déjeuner');if(meal===null)return;if(!['Petit-déjeuner','Déjeuner','Dîner','Collation'].includes(meal))return toast('Repas non reconnu');let t=recipeTotals(r);await put('entries',{id:uid(),foodId:r.id,name:r.name,date,grams:100,meal,...t});toast('Une portion ajoutée au journal');render()});$('#weightForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(n(f.kg)<=0)return;await put('weights',{id:f.date,date:f.date,kg:n(f.kg)});toast('Poids enregistré');render()});$('#settingsForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));await put('settings',{...(await all('settings'))[0],id:'main',...Object.fromEntries(Object.entries(f).map(([k,v])=>[k,n(v)]))});toast('Objectifs enregistrés');render()});$('#energyForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),age=Number(f.get('age')),height=Number(f.get('height')),weight=Number(f.get('weight')),factor=Number(f.get('activity')),delta=Number(f.get('goal'));if(!Number.isFinite(age)||age<18||age>110||!Number.isFinite(height)||height<100||height>250||!Number.isFinite(weight)||weight<25||weight>350||!Number.isFinite(factor)||factor<1.2||factor>1.725||!Number.isFinite(delta))return toast('Valeurs non valides');const bmr=10*weight+6.25*height-5*age+(f.get('formula')==='male'?5:-161),maintenance=Math.round(bmr*factor),target=Math.max(1200,Math.round(maintenance+delta));const result=$('#energyResult');result.innerHTML=`<p class="notice">Métabolisme basal estimé : <b>${fmt(bmr)} kcal</b><br>Dépense quotidienne estimée : <b>${fmt(maintenance)} kcal</b><br>Objectif calculé : <b>${fmt(target)} kcal/j</b>. Ce résultat est approximatif et doit être adapté à votre situation.</p><button type="button" id="applyEnergy" class="btn">Appliquer cet objectif calorique</button>`;$('#applyEnergy').onclick=async()=>{if(!confirm('Remplacer uniquement votre objectif calorique par '+target+' kcal/j ?'))return;const current=(await all('settings'))[0]||{id:'main'};await put('settings',{...current,target});toast('Objectif calorique mis à jour');render()}});$('#reminderForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);const valid=x=>/^([01]\d|2[0-3]):[0-5]\d$/.test(x);const mealTime=String(f.get('mealTime')||''),waterTime=String(f.get('waterTime')||'');if(!valid(mealTime)||!valid(waterTime))return toast('Horaires invalides');const current=(await all('settings'))[0]||{id:'main'};await put('settings',{...current,mealTime,waterTime,remindersEnabled:f.has('remindersEnabled')});toast('Rappels enregistrés');render()});$('#testReminder')?.addEventListener('click',async()=>{if(!('Notification' in window)){toast('Notifications non disponibles sur cet appareil');return}let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission==='granted'){try{new Notification('NUTRI',{body:'Ceci est un rappel de test.'})}catch{toast('Notification indisponible')}}else toast('Notifications non autorisées')});$('#persistBtn')?.addEventListener('click',requestPersistence);if(tab==='profile'){let age=localStorage.getItem(BACKUP_KEY);$('#backupAge').textContent=age?'Dernière sauvegarde préparée : '+new Date(age).toLocaleString('fr-FR')+' (vérifiez sa présence dans Fichiers)':'Aucune sauvegarde connue sur cet appareil';storageStatus().then(t=>{let el=$('#storageStatus');if(el)el.textContent=t})}$('#exportBtn')?.addEventListener('click',backup);$('#importBtn')?.addEventListener('click',()=>$('#importFile').click());$('#importFile')?.addEventListener('change',restore)}async function backup(){try{if(!crypto?.subtle)throw Error('Chiffrement indisponible : utilisez HTTPS');let password=prompt('Mot de passe de sauvegarde (12 caractères minimum) :');if(password===null)return;if(password.length<12)throw Error('Choisissez au moins 12 caractères');let confirmation=prompt('Confirmez le mot de passe :');if(confirmation!==password)throw Error('Les mots de passe ne correspondent pas');let data={app:'NUTRI',version:3,exportedAt:new Date().toISOString(),stores:{}};for(let s of STORES)data.stores[s]=await all(s);validate(data);let payload=await seal(data,password);let check=await unseal(JSON.parse(payload),password);validate(check);let blob=new Blob([payload],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`NUTRI_sauvegarde_${today()}.nutri`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);localStorage.setItem(BACKUP_KEY,new Date().toISOString());toast('Fichier préparé : enregistrez-le dans Fichiers');render()}catch(err){alert('Sauvegarde impossible : '+err.message)}}async function restore(e){let file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('Fichier trop volumineux');let wrapper=JSON.parse(await file.text()),data;if(wrapper.format==='NUTRI-ENCRYPTED'){let password=prompt('Mot de passe de la sauvegarde :');if(password===null)return;try{data=await unseal(wrapper,password)}catch{throw Error('Mot de passe incorrect ou fichier endommagé')}}else{if(!confirm('Ancienne sauvegarde non chiffrée détectée. Voulez-vous continuer ?'))return;data=wrapper}validate(data);if(!confirm('Remplacer toutes les données locales par cette sauvegarde ? Cette opération est irréversible.'))return;await new Promise((resolve,reject)=>{let tx=db.transaction(STORES,'readwrite');for(let s of STORES){let store=tx.objectStore(s);store.clear();for(let item of data.stores[s])store.put(item)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});toast('Restauration terminée');render()}catch(err){alert('Restauration impossible : '+err.message)}finally{e.target.value=''}}

let scanStream=null,scanTimer=null,scanBusy=false;function scanMessage(message){const el=$('#scanStatus');if(el)el.textContent=message}function validBarcode(code){return /^\d{8,14}$/.test(String(code||''))}function scanDetected(code){code=String(code||'').replace(/\D/g,'');if(!validBarcode(code))return false;stopScan();const input=$('#barcodeInput');if(input)input.value=code;scanMessage('Code détecté : '+code);lookupBarcode(code);return true}
function stopScan(){scanBusy=false;if(scanTimer){clearInterval(scanTimer);scanTimer=null}if(scanStream){scanStream.getTracks().forEach(t=>t.stop());scanStream=null}let v=$('#scanVideo');if(v){v.srcObject=null;v.classList.add('hidden')}$('#scanStop')?.classList.add('hidden')}
async function lookupBarcode(code){let target=$('#barcodeResults');if(!target)return;target.textContent='Recherche du produit…';try{let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000),r;try{r=await fetch('https://world.openfoodfacts.org/api/v2/product/'+encodeURIComponent(code)+'.json?fields=code,product_name,brands,nutriments',{signal:controller.signal})}finally{clearTimeout(timer)}if(!r.ok)throw Error('Service indisponible');let data=await r.json(),p=data.product;if(data.status!==1||!p?.product_name)throw Error('Produit introuvable');let v=offNutriments(p);target.innerHTML=`<div class="entry"><div><b>${esc(p.product_name)}</b><small>${esc(p.brands||'')} · ${fmt(v.kcal)} kcal / 100 g · P ${fmt(v.protein)} g · G ${fmt(v.carbs)} g · L ${fmt(v.fat)} g</small></div><button class="btn small" id="saveBarcode">Enregistrer</button></div>`;$('#saveBarcode').onclick=async()=>{await put('foods',{id:'off:'+code,name:String(p.product_name).slice(0,120),brand:String(p.brands||'').slice(0,120),barcode:code,source:'Open Food Facts',...v});toast('Produit enregistré');render()}}catch(e){target.textContent='Recherche impossible : '+e.message}}
function bindExtended(){
$('#planDate')?.addEventListener('change',e=>{date=e.target.value;render()});
$('#planForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),servings=Number(f.get('servings')),recipeId=String(f.get('recipeId')||'');if(!Number.isFinite(servings)||servings<0.25||servings>50||!(await all('recipes')).some(r=>r.id===recipeId))return toast('Recette ou portions invalides');await put('plans',{id:uid(),date,recipeId,meal:String(f.get('meal')),servings});toast('Menu planifié');render()});
document.querySelectorAll('[data-plan-delete]').forEach(b=>b.onclick=async()=>{await del('plans',b.dataset.planDelete);render()});
$('#copyShopping')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(window.__nutriShopping);toast('Liste copiée')}catch{toast('Copie non disponible sur cet appareil')}}); 
$('#barcodeForm')?.addEventListener('submit',e=>{e.preventDefault();let code=$('#barcodeInput').value.trim();if(validBarcode(code))lookupBarcode(code);else scanMessage('Saisissez 8 à 14 chiffres.')});
$('#scanStart')?.addEventListener('click',async()=>{if(!('BarcodeDetector'in window)){scanMessage('Lecture automatique non prise en charge par ce navigateur. Utilisez une photo ou saisissez le code.');return}if(!navigator.mediaDevices?.getUserMedia){scanMessage('Caméra indisponible : utilisez HTTPS et autorisez la caméra.');return}try{let detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']}),v=$('#scanVideo');scanMessage('Ouverture de la caméra…');scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});v.srcObject=scanStream;v.classList.remove('hidden');$('#scanStop').classList.remove('hidden');await v.play();scanMessage('Placez le code-barres au centre de l’image.');scanTimer=setInterval(async()=>{if(scanBusy||!scanStream||v.readyState<2||document.visibilityState!=='visible')return;scanBusy=true;try{let found=await detector.detect(v);for(const item of found){if(scanDetected(item.rawValue))break}}catch(e){console.warn('Lecture code-barres',e)}finally{scanBusy=false}},700)}catch(e){stopScan();scanMessage('Caméra inaccessible : '+e.message+'. Utilisez une photo ou la saisie manuelle.')}});
$('#scanStop')?.addEventListener('click',()=>{stopScan();scanMessage('Lecture arrêtée.')});$('#barcodePhoto')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>12*1024*1024)throw Error('Image trop volumineuse (12 Mo maximum)');if(!('BarcodeDetector'in window))throw Error('Décodage photo non pris en charge sur ce navigateur');scanMessage('Analyse de la photo…');const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']});const bitmap=await createImageBitmap(file);try{const found=await detector.detect(bitmap);if(!found.some(item=>scanDetected(item.rawValue)))scanMessage('Aucun code détecté. Essayez une image plus nette ou saisissez le code.')}finally{bitmap.close()}}catch(err){scanMessage(err.message+' — saisissez le code manuellement.')}finally{e.target.value=''}});
$('#fastStart')?.addEventListener('submit',async e=>{e.preventDefault();let hours=Number(new FormData(e.target).get('hours'));await put('fasting',{id:uid(),start:new Date().toISOString(),hours});render()});
$('#fastStop')?.addEventListener('click',async()=>{let a=(await all('fasting')).find(x=>!x.end);if(a){a.end=new Date().toISOString();await put('fasting',a);render()}});
document.querySelectorAll('[data-fast-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Supprimer cette session ?')){await del('fasting',b.dataset.fastDelete);render()}});
}

const reminderSeen=new Set();async function checkReminders(){if(!db||document.visibilityState!=='visible')return;try{const cfg=(await all('settings'))[0];if(!cfg?.remindersEnabled)return;const now=new Date(),hhmm=now.toTimeString().slice(0,5),day=today();for(const [kind,time,message] of [['meal',cfg.mealTime,'Pensez à compléter votre journal alimentaire.'],['water',cfg.waterTime,'Pensez à votre hydratation.']]){const key=day+':'+kind;if(time===hhmm&&!reminderSeen.has(key)){reminderSeen.add(key);toast(message);if('Notification'in window&&Notification.permission==='granted')try{new Notification('NUTRI',{body:message})}catch{}}}for(const key of reminderSeen)if(!key.startsWith(day+':'))reminderSeen.delete(key)}catch(e){console.warn('Rappel :',e)}}setInterval(checkReminders,30000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkReminders()});async function start(){try{db=await openDB();if(!(await all('settings')).length)await put('settings',{id:'main',target:2000,protein:100,carbs:220,fat:70,waterTarget:2000});render();checkReminders();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(console.warn)}catch(err){$('#app').innerHTML=`<main class="shell"><h1>NUTRI</h1><p>Le stockage local n'est pas accessible. Ouvrez l'application depuis un site HTTPS, sans navigation privée.</p><p class="notice">${esc(err.message)}</p></main>`}}start();

window.addEventListener('pagehide',stopScan);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')stopScan()});

let photoObjectURL=null;
function clearPhotoURL(){if(photoObjectURL){URL.revokeObjectURL(photoObjectURL);photoObjectURL=null}}
function photoRow(foods){return `<div class="formgrid photo-food-row" style="align-items:end"><label class="field">Aliment<select name="foodId" required><option value="">Choisir un aliment</option>${foods.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label><label class="field">Quantité (g)<input type="number" name="grams" min="1" max="10000" step="1" value="100" required></label><button type="button" class="btn alt photo-remove">Retirer</button></div>`}
async function bindPhotoMeal(){const form=$('#photoMealForm');if(!form)return;const foods=await all('foods'),rows=$('#photoMealRows');function addRow(){rows.insertAdjacentHTML('beforeend',photoRow(foods));update()}function update(){let items=[];for(let row of rows.querySelectorAll('.photo-food-row')){let f=foods.find(x=>x.id===row.querySelector('[name=foodId]').value),g=Number(row.querySelector('[name=grams]').value);if(f&&Number.isFinite(g)&&g>0&&g<=10000)items.push({...f,grams:g})}let t=totals(items);$('#photoTotal').textContent=`${items.length} aliment(s) · ${fmt(t.kcal)} kcal · Protéines ${fmt(t.protein)} g · Glucides ${fmt(t.carbs)} g · Lipides ${fmt(t.fat)} g`}
rows.addEventListener('change',update);rows.addEventListener('input',update);rows.addEventListener('click',e=>{if(e.target.closest('.photo-remove')){e.target.closest('.photo-food-row').remove();update()}});$('#photoAddRow').onclick=addRow;addRow();
$('#mealPhoto').onchange=e=>{clearPhotoURL();let f=e.target.files?.[0],preview=$('#mealPreview'),status=$('#mealPhotoStatus');preview.classList.add('hidden');if(!f)return;if(!f.type.startsWith('image/')){status.textContent='Sélectionnez une image valide.';return}if(f.size>15*1024*1024){status.textContent='Image trop volumineuse (maximum 15 Mo).';return}photoObjectURL=URL.createObjectURL(f);preview.src=photoObjectURL;preview.classList.remove('hidden');status.textContent='Image affichée localement, non enregistrée ni envoyée.'};
form.onsubmit=async e=>{e.preventDefault();try{let items=[];for(let row of rows.querySelectorAll('.photo-food-row')){let f=foods.find(x=>x.id===row.querySelector('[name=foodId]').value),g=Number(row.querySelector('[name=grams]').value);if(!f||!Number.isFinite(g)||g<=0||g>10000)throw Error('Aliment ou quantité invalide');items.push({id:uid(),date,meal:form.elements.meal.value,foodId:f.id,name:f.name,grams:g,kcal:n(f.kcal),protein:n(f.protein),carbs:n(f.carbs),fat:n(f.fat)})}if(!items.length)throw Error('Ajoutez au moins un aliment');await new Promise((resolve,reject)=>{let tx=db.transaction('entries','readwrite'),store=tx.objectStore('entries');for(let item of items)store.put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});clearPhotoURL();tab='diary';toast('Repas ajouté au journal');render()}catch(err){toast(err.message)}}}
window.addEventListener('pagehide',clearPhotoURL);
